module IIC_Driver(
	sys_clk,
	rst_n,
	IICSlave,
	IICWriteReq,
	IICWriteData,
	IICSCL,
	IICWriteDone,
	IICSDA);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	input [15:0] IICSlave;
	input IICWriteReq;
	input [7:0] IICWriteData;
	output IICSCL;
	output IICWriteDone;
	inout IICSDA;

	wire sys_clk;
	wire rst_n;
	wire [15:0] IICSlave;
	wire IICWriteReq;
	wire [7:0] IICWriteData;
	wire IICSCL;
	wire IICWriteDone;
	wire IICSDA;

	//----Code starts here: integrated by Robei-----
	localparam IIC_IDLE       =   5'b00_001;  //空闲态
	localparam IIC_START      =   5'b00_010;  //起始态
	localparam IIC_WRDATA     =   5'b00_100;  //写数据态
	
	localparam IIC_ACK        =   5'b01_000;  //应答态
	localparam IIC_STOP       =   5'b10_000;  //停止态
	
	
	
	localparam  IIC_Pre       =   'd100;     //iiC分频
	    
	reg[5:0]   state , next_state;
	reg[21:0]  IICCnt;              //IIC计数器
	reg[3:0]   IICBitCnt;           //IIC数据发送个数计数
	reg[1:0]   IICACKStopCnt;       //IIC ack stop应答计数
	reg[2:0]   IICSendBytes;        //IIC发送数据字节计数
	
	
	reg[15:0]   IICSlaveReg;           //从机地址+寄存器数据
	//reg[7:0]   IICReadDataReg;         //读取到的数据
	
	
	reg 	IICWriteReqReg;
	
	reg   iictx;     //iic发送数据引脚
	reg   iicCLK;    //iic时钟信号引脚
	
	assign IICSDA =(state == IIC_ACK) ? 1'bz : iictx;  //iic为读数据或者应答的时候，输出为高阻态
	assign IICSCL =  iicCLK;
	
	//assign IICReadData = IICReadDataReg;
	
	assign IICReadDone  = (state != next_state && state == IIC_STOP) ? 1'b1 : 1'b0;
	assign IICWriteDone = (state != next_state && state == IIC_STOP) ? 1'b1 : 1'b0;
	
	
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			IICWriteReqReg <= 1'b0;
		else if(IICWriteDone == 1'b1)
			IICWriteReqReg <= 1'b0;
		else if(IICWriteReq == 1'b1)
		   IICWriteReqReg <= 1'b1;
		else
			IICWriteReqReg <= IICWriteReqReg;
	
	end
	
	always @(posedge sys_clk or negedge rst_n) 
	begin
	    if(rst_n == 1'b0)
	        state <= IIC_IDLE;
	    else
	        state <= next_state;   
	end
	
	always @(*)
	begin
	    case(state)
	    IIC_IDLE: 
	        if(IICWriteReq == 1'b1 )
	            next_state <= IIC_START;
	        else
	            next_state <= IIC_IDLE;
	    IIC_START:
	        if(IICCnt == (IIC_Pre * 'd2))
	            next_state <= IIC_WRDATA;
	        else
	            next_state <= IIC_START;
	    IIC_WRDATA:
	        if(IICBitCnt == 'd8 && iicCLK == 1'b0)
	            next_state <= IIC_ACK;
	        else
	            next_state <= IIC_WRDATA;
	    
	    IIC_ACK:
	        if(IICACKStopCnt == 'd1 && iicCLK == 1'b0)
	            if(IICSendBytes == 'd2) 
	                if(IICWriteReqReg == 1'b1)            //三个字节发送完成，进入停止态
	                    next_state <= IIC_STOP;
	                
	            else if(IICSendBytes == 'd2 )
	                next_state <= IIC_START;
	            else if(IICSendBytes == 'd4)
	                next_state <= IIC_STOP;
	            else
	                next_state <= IIC_WRDATA;
	        else
	            next_state <= IIC_ACK;
	    IIC_STOP:
	        if(IICACKStopCnt == 'd1 && IICCnt == IIC_Pre/4 && iicCLK == 1'b1)
	            next_state <= IIC_IDLE;
	        else
	            next_state <= IIC_STOP;
	    default:  next_state <= IIC_IDLE;
	    endcase
	end
	
	
	
	//iic发送字节计数
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICSendBytes <= 'd0;
	    else if(state == IIC_IDLE)
	        IICSendBytes <= 'd0;
	    else if(state == IIC_ACK)
	        if(next_state != state)
	            IICSendBytes <= IICSendBytes + 1'b1;
	        else
	            IICSendBytes <= IICSendBytes;
	    else
	        IICSendBytes <= IICSendBytes;
	
	end
	
	//IIC分频计数
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICCnt <= 'd0;
	    else if(IICCnt == IIC_Pre && state != IIC_START)
	        IICCnt <= 'd0;
	    else if(IICCnt == (IIC_Pre *'d2) && state != IIC_START)
	        IICCnt <= 'd0;
	    else if(state != next_state)
	        IICCnt <= 'd0;
	    else if(state == IIC_START)
	        IICCnt <= IICCnt + 1'b1;
	    else if(state == IIC_WRDATA )
	        IICCnt <= IICCnt + 1'b1;
	  
	    else if(state == IIC_ACK)
	        IICCnt <= IICCnt + 1'b1;
	    else if(state == IIC_STOP)
	        IICCnt <= IICCnt + 1'b1;
	end
	//iic发送bit计数
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICBitCnt <= 'd0;
	    else if(state == IIC_IDLE || state == IIC_ACK)
	        IICBitCnt <= 'd0;
	    else if(state == IIC_WRDATA && IICCnt == (IIC_Pre /2))
	        if(iicCLK == 1'b1)
	            IICBitCnt <= IICBitCnt + 1'b1;
	        else
	            IICBitCnt <= IICBitCnt;
	   
	    else
	        IICBitCnt <= IICBitCnt;
	end
	
	
	//IIC ack stop 应答计数
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICACKStopCnt <= 'd0;
	    else if(state != next_state)
	        IICACKStopCnt <= 'd0;
	    else if((state == IIC_ACK || state == IIC_STOP) && IICCnt == (IIC_Pre /2))
	        if(iicCLK == 1'b1)
	            IICACKStopCnt <= IICACKStopCnt + 1'b1;
	        else
	            IICACKStopCnt <= IICACKStopCnt;
	    else if(state == IIC_ACK || state == IIC_STOP)
	        IICACKStopCnt <= IICACKStopCnt;
	    else
	        IICACKStopCnt <= 'd0;
	end
	
	//IIC从机信息控制
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICSlaveReg <= 'd0;
	    else if((IICWriteReq == 1'b1) && state == IIC_IDLE)  //请求来时，保存信息
	        IICSlaveReg <= IICSlave;
	    else if(state == IIC_ACK && state != next_state)   //每发送完成一字节，就调换数据，始终发送的是低8位
	        if(IICSendBytes == 'd2)
	            IICSlaveReg <= {IICSlaveReg[7:0],IICSlaveReg[15:8]} + 1'b1;
	        else
	            IICSlaveReg <= {IICSlaveReg[7:0],IICSlaveReg[15:8]};
	    else
	        IICSlaveReg <= IICSlaveReg;
	end
	
	
	//IIC 时钟控制 
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        iicCLK <= 1'b1;
	    else if(state == IIC_START && IICCnt == (IIC_Pre*2))      //开始结束时，拉低时钟线
	        iicCLK <= 1'b0;
	    else if(state == IIC_START && IICCnt > IIC_Pre)
	        iicCLK <= 1'b1;
	    else if(state == IIC_START && IICCnt == IIC_Pre)
	        iicCLK <= iicCLK;
	    else if(state == IIC_WRDATA && IICCnt == IIC_Pre)     //发送数据，依次取反时钟线
	        iicCLK <= ~iicCLK;
	    
	    else if(state == IIC_ACK && IICCnt == IIC_Pre)
	        iicCLK <= ~iicCLK;
	    else if(state == IIC_STOP && IICCnt == IIC_Pre)  //在停止态时，IICCnt时，直接拉高iicCLK
	        iicCLK <= 1'b1;
	end
	
	
	//iic发送控制
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)   
	        iictx <= 1'b1;
	    else if(state == IIC_START && IICCnt == (IIC_Pre/2))      //开始，iic数据线拉低
	        iictx <= 1'b0;
	    else if(state == IIC_START && IICCnt == IIC_Pre/4)      //开始，iic数据线拉低
	        iictx <= 1'b1;
	    else if(state == IIC_WRDATA && IICCnt == IIC_Pre / 2)     //iic发送数据
	        if(iicCLK == 1'b0 && IICSendBytes == 'd2 && (IICWriteReq == 1'b1 || IICWriteReqReg == 1'b1))
	            iictx <= IICWriteData['d7-IICBitCnt];
	        else if(iicCLK == 1'b0)
	            iictx <= IICSlaveReg['d7-IICBitCnt];
	        else
	            iictx <= iictx;
	    else if(state == IIC_ACK)
	        iictx <= 1'b0;
	
	    else if(state == IIC_STOP && IICCnt == (IIC_Pre))
	        if(iicCLK == 1'b1)
	            iictx <= 1'b1;
	        else
	            iictx <= iictx;
	    else if(state == IIC_IDLE)
	        iictx <= 1'b1;
	end
	
	
	
endmodule    //IIC_Driver

